<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import type {FormInstance,FormProps} from 'ant-design-vue';
import {submitForm,api,dateTime,matches,pagination,showError,useActions,type Row} from './api';
import AppIcon from './AppIcon.vue';import PagePanel from './PagePanel.vue';
const rows=ref<Row[]>([]),loading=ref(false),loadError=ref(''),search=ref(''),status=ref('all'),detail=ref<Row|null>(null),sourceOpen=ref(false),editId=ref<string|null>(null),formRef=ref<FormInstance>();
const emptySource=()=>({code:'',displayName:'',host:'',port:3306,databaseName:'',readUsername:'',password:''});const form=ref(emptySource());
const {busy,perform}=useActions();
const rules=computed<FormProps['rules']>(()=>({code:[{required:true,message:'请输入编码'},{pattern:/^[A-Za-z][A-Za-z0-9_]{0,63}$/,message:'以字母开头，仅支持字母、数字和下划线，最多 64 位'}],displayName:[{required:true,whitespace:true,message:'请输入名称'},{max:128,message:'名称不能超过 128 个字符'}],host:[{required:true,message:'请输入数据库地址'},{pattern:/^[A-Za-z0-9.-]{1,253}$/,message:'请输入有效的 IP 或主机名'}],port:[{required:true,type:'number',min:1,max:65535,message:'请输入有效端口'}],databaseName:[{required:true,message:'请输入数据库名'},{pattern:/^[A-Za-z][A-Za-z0-9_]{0,63}$/,message:'以字母开头，仅支持字母、数字和下划线'}],readUsername:[{required:true,message:'请输入数据库用户名'},{pattern:/^[A-Za-z0-9_]{1,80}$/,message:'仅支持字母、数字和下划线'}],password:[{required:!editId.value,message:'请输入数据库密码'},{max:4096,message:'密码过长'}]}));
const filtered=computed(()=>rows.value.filter(row=>matches(row,search.value,['displayName','code','host','databaseName'])&&(status.value==='all'||Boolean(row.enabled)===(status.value==='enabled'))));
const enabled=computed(()=>rows.value.filter(r=>r.enabled).length),tableCount=computed(()=>rows.value.reduce((sum,r)=>sum+Number(r.allowedTables||0),0));
async function refresh(){loading.value=true;loadError.value='';try{rows.value=await api('/api/sources')}catch(e){loadError.value=(e as Error).message}finally{loading.value=false}}
function create(){editId.value=null;form.value=emptySource();sourceOpen.value=true}
async function showDetail(row:Row){try{detail.value=await api('/api/sources/'+row.id)}catch(e){showError(e)}}
async function edit(row:Row){try{const data=await api<Row>('/api/sources/'+row.id);editId.value=row.id;form.value={code:data.code,displayName:data.displayName,host:data.host,port:data.port,databaseName:data.databaseName,readUsername:data.readUsername,password:''};detail.value=null;sourceOpen.value=true}catch(e){showError(e)}}
async function save(){const result=await perform(editId.value?'/api/sources/'+editId.value:'/api/sources',form.value,editId.value?'PUT':'POST',editId.value?'数据源已更新':'数据源已创建');if(result){sourceOpen.value=false;form.value.password='';await refresh()}}
async function toggle(row:Row){if(await perform('/api/sources/'+row.id+(row.enabled?'/disable':'/enable'),{},'POST',row.enabled?'数据源已停用':'数据源已启用'))await refresh()}
async function test(row:Row){await perform('/api/sources/'+row.id+'/test',{},'POST','连接测试通过')}
const grantSource=ref<Row|null>(null),tableRows=ref<Row[]>([]),columnRows=ref<Row[]>([]),selectedTable=ref(''),grantInput=ref(''),grantLoading=ref(false);
async function loadGrants(){if(!grantSource.value)return;grantLoading.value=true;try{if(selectedTable.value)columnRows.value=await api('/api/sources/'+grantSource.value.id+'/allowlist/'+encodeURIComponent(selectedTable.value)+'/columns');else tableRows.value=await api('/api/sources/'+grantSource.value.id+'/allowlist')}catch(e){showError(e)}finally{grantLoading.value=false}}
async function openGrants(row:Row){grantSource.value=row;selectedTable.value='';grantInput.value='';await loadGrants()}
async function openColumns(row:Row){selectedTable.value=row.tableName;grantInput.value='';await loadGrants()}
async function addGrant(){if(!grantSource.value||!grantInput.value.trim())return;const value=grantInput.value.trim();if(!/^[A-Za-z][A-Za-z0-9_]{0,63}$/.test(value)){showError(Error('名称须以字母开头，仅包含字母、数字和下划线，最多 64 位'));return}const path='/api/sources/'+grantSource.value.id+'/allowlist'+(selectedTable.value?'/'+encodeURIComponent(selectedTable.value)+'/columns':'');if(await perform(path,selectedTable.value?{columnName:value}:{tableName:value},'POST','授权已添加')){grantInput.value='';await loadGrants();await refresh()}}
async function revokeGrant(row:Row){if(!grantSource.value)return;const path='/api/sources/'+grantSource.value.id+'/allowlist/'+encodeURIComponent(selectedTable.value||row.tableName)+(selectedTable.value?'/columns/'+encodeURIComponent(row.columnName):'');if(await perform(path,undefined,'DELETE','授权已撤销')){await loadGrants();await refresh()}}
async function enableTable(row:Row){if(grantSource.value&&await perform('/api/sources/'+grantSource.value.id+'/allowlist',{tableName:row.tableName},'POST','表授权已启用')){await loadGrants();await refresh()}}
watch(sourceOpen,open=>{if(!open){form.value.password='';formRef.value?.clearValidate()}});onMounted(refresh);defineExpose({refresh});
</script>
<template>
 <a-alert v-if="loadError" :message="loadError" type="error" show-icon class="dg-notice"/>
 <div class="dg-summary"><div><span>数据源总数</span><strong>{{rows.length}}</strong></div><div><span>已启用</span><strong>{{enabled}}</strong></div><div><span>已停用</span><strong>{{rows.length-enabled}}</strong></div><div><span>已授权数据表</span><strong>{{tableCount}}</strong></div></div>
 <PagePanel title="数据源列表"><template #actions><a-button type="primary" @click="create"><AppIcon name="plus"/>新建数据源</a-button></template><template #filters><a-input v-model:value="search" allow-clear placeholder="搜索名称、编码或主机" class="dg-search" aria-label="搜索数据源"><template #prefix><AppIcon name="search"/></template></a-input><a-select v-model:value="status" class="dg-select" aria-label="数据源状态" :options="[{value:'all',label:'全部状态'},{value:'enabled',label:'已启用'},{value:'disabled',label:'已停用'}]"/><span class="dg-filter-count">共 {{filtered.length}} 个数据源</span></template>
 <a-table :data-source="filtered" :loading="loading" :pagination="pagination" row-key="id" :scroll="{x:1050}"><a-table-column title="数据源" :width="225"><template #default="{record}"><div class="dg-name-cell"><span class="dg-resource-icon"><AppIcon name="sources"/></span><div><strong>{{record.displayName}}</strong><small>{{record.code}}</small></div></div></template></a-table-column><a-table-column title="连接地址"><template #default="{record}">{{record.host}}:{{record.port}}</template></a-table-column><a-table-column title="数据库" data-index="databaseName"/><a-table-column title="授权表数" data-index="allowedTables"/><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="record.enabled?'good':'off'">{{record.enabled?'已启用':'已停用'}}</span></template></a-table-column><a-table-column title="操作" align="right" :width="320"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" @click="showDetail(record)">详情</a-button><a-button type="link" :loading="busy" @click="test(record)">连接测试</a-button><a-button type="link" @click="openGrants(record)">授权管理</a-button><a-button type="link" :disabled="record.enabled" @click="edit(record)">编辑</a-button><a-popconfirm v-if="record.enabled" title="停用后将拒绝新的读取请求，确认停用？" ok-text="停用" cancel-text="取消" @confirm="toggle(record)"><a-button type="link" class="dg-muted-action">停用</a-button></a-popconfirm><a-button v-else type="link" :disabled="busy" @click="toggle(record)">启用</a-button></div></template></a-table-column></a-table></PagePanel>
 <a-modal v-model:open="sourceOpen" :title="editId?'编辑数据源':'新建 MySQL 数据源'" centered :width="620" ok-text="保存" cancel-text="取消" :confirm-loading="busy" :mask-closable="!busy" :closable="!busy" :cancel-button-props="{disabled:busy}" @ok="submitForm(formRef,save)"><a-form ref="formRef" :model="form" :rules="rules" layout="vertical" @finish="save"><div class="dg-form-grid"><a-form-item label="名称" name="displayName"><a-input v-model:value="form.displayName" placeholder="数据源名称"/></a-form-item><a-form-item label="编码" name="code"><a-input v-model:value="form.code" placeholder="例如 db01"/></a-form-item><a-form-item label="IP 或主机名" name="host"><a-input v-model:value="form.host" placeholder="例如 192.168.197.129"/></a-form-item><a-form-item label="端口" name="port"><a-input-number v-model:value="form.port" :min="1" :max="65535"/></a-form-item><a-form-item label="数据库" name="databaseName"><a-input v-model:value="form.databaseName"/></a-form-item><a-form-item label="用户名" name="readUsername"><a-input v-model:value="form.readUsername" autocomplete="off"/></a-form-item><a-form-item class="dg-form-full" label="密码" name="password"><a-input-password v-model:value="form.password" :placeholder="editId?'留空保留原密码':'数据库密码'" autocomplete="new-password"/></a-form-item></div></a-form></a-modal>
 <a-modal :open="!!detail" title="数据源详情" centered :width="600" :footer="null" @cancel="detail=null"><a-descriptions v-if="detail" :column="2" layout="vertical"><a-descriptions-item label="名称">{{detail.displayName}}</a-descriptions-item><a-descriptions-item label="编码">{{detail.code}}</a-descriptions-item><a-descriptions-item label="连接地址">{{detail.host}}:{{detail.port}}</a-descriptions-item><a-descriptions-item label="数据库">{{detail.databaseName}}</a-descriptions-item><a-descriptions-item label="用户名">{{detail.readUsername}}</a-descriptions-item><a-descriptions-item label="状态">{{detail.enabled?'已启用':'已停用'}}</a-descriptions-item><a-descriptions-item label="创建时间">{{dateTime(detail.createdAt)}}</a-descriptions-item></a-descriptions><div class="dg-modal-footer"><a-button @click="detail=null">关闭</a-button></div></a-modal>
 <a-modal :open="!!grantSource" :title="(grantSource?.displayName||'')+' 授权管理'" centered :width="740" :footer="null" @cancel="grantSource=null"><div class="dg-grant-heading"><a-button v-if="selectedTable" type="link" @click="selectedTable='';grantInput='';loadGrants()">返回数据表</a-button><strong>{{selectedTable?selectedTable+' 的展示字段':'允许读取的数据表'}}</strong></div><form class="dg-inline-form" @submit.prevent="addGrant"><a-input v-model:value="grantInput" :placeholder="selectedTable?'输入字段名':'输入数据表名'" :aria-label="selectedTable?'字段名':'表名'" :maxlength="64"/><a-button type="primary" html-type="submit" :loading="busy" :disabled="!grantInput.trim()">添加授权</a-button></form><p v-if="selectedTable" class="dg-field-note">未授权的字段将保持脱敏。</p><a-table :data-source="selectedTable?columnRows:tableRows" :loading="grantLoading" :row-key="selectedTable?'columnName':'id'" :pagination="{pageSize:6}"><a-table-column :title="selectedTable?'字段名':'数据表'" :data-index="selectedTable?'columnName':'tableName'"/><a-table-column title="状态"><template #default="{record}"><span class="dg-status" :class="record.enabled?'good':'off'">{{record.enabled?'已授权':'已撤销'}}</span></template></a-table-column><a-table-column title="操作" align="right"><template #default="{record}"><div class="dg-row-actions"><a-button v-if="!selectedTable&&record.enabled" type="link" @click="openColumns(record)">字段授权</a-button><a-popconfirm v-if="record.enabled" title="确认撤销此项授权？" ok-text="撤销" cancel-text="取消" @confirm="revokeGrant(record)"><a-button type="link" danger>撤销</a-button></a-popconfirm><a-button v-else-if="!selectedTable" type="link" @click="enableTable(record)">重新授权</a-button><a-button v-else type="link" @click="grantInput=record.columnName;addGrant()">重新授权</a-button></div></template></a-table-column></a-table></a-modal>
</template>
